mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.2) * p.xz;
  float d = length(p + vec3(0.0, 1.2, 0.0)) - 0.5;
  vec3 q = p;
  for (int i = 0; i < 4; i++) {
    q = abs(q) - vec3(0.4, 0.3, 0.4);
    q.xy = rot(0.6) * q.xy;
    q.yz = rot(0.4) * q.yz;
    d = min(d, length(q) - 0.12);
  }
  return d;
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.5, -3.2);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  float glow = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    glow += 0.015 / (0.05 + abs(d));
    if (d < 0.003 || t > 8.0) break;
    t += d * 0.75;
  }
  vec3 col = glow * vec3(0.0, 1.0, 0.75) * (0.8 + 0.4 * bass);
  ret = col;
}
